// 骰子 / 跑团检定
//
// 流程刻意是「先设定后果，再投」：
//   填『判定什么』『成功会怎样』『失败会怎样』→ 点骰子 → 出结果 + 对应后果。
// 反过来（先投再想后果）会让人不自觉地按骰面去编，检定就失去意义了。
//
// 高度由宿主的 ResizeObserver 自动量，插件不用管（见 pluginSrcDoc.js）。

var el = {};
['subject','onwin','onlose','dc','mod','adv','d20','dval','stage','tip','verdict','detail','outcome','send','reset','free','freetoggle','freerow','formula','rollf','err'].forEach(function(k){ el[k]=document.getElementById(k); });

var adv = 0;
var last = null;
var canSend = false, canDraft = false;
var rolling = false;
var REDUCED = false;
try { REDUCED = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){}

function d(sides){
  // crypto 比 Math.random 适合『掷骰』这种用户会在意公平性的场景
  if(window.crypto && window.crypto.getRandomValues){
    var b=new Uint32Array(1); window.crypto.getRandomValues(b); return (b[0]%sides)+1;
  }
  return Math.floor(Math.random()*sides)+1;
}

// ── 优势 / 劣势 ──
Array.prototype.forEach.call(el.adv.children, function(b){
  b.addEventListener('click', function(){
    adv = parseInt(b.getAttribute('data-adv'),10) || 0;
    Array.prototype.forEach.call(el.adv.children, function(x){ x.className='advb'; });
    b.className='advb on';
  });
});

// ── 动画 ──
// 结果先算好，动画只是把它演出来 —— 不阻塞逻辑，也不会因为动画被打断而丢结果。
function animate(finalText, done){
  if(REDUCED){ el.dval.textContent=finalText; done(); return; }
  rolling = true;
  el.stage.className='';
  el.d20.setAttribute('class','rolling');
  var t = setInterval(function(){ el.dval.textContent = String(d(20)); }, 55);
  setTimeout(function(){
    clearInterval(t);
    el.d20.setAttribute('class','');
    el.dval.textContent = finalText;
    void el.stage.offsetWidth;   // 强制重排，让连续投掷也能重播动画
    el.stage.className='settle';
    rolling = false;
    done();
  }, 620);
}

// ── 检定 ──
function doCheck(){
  if(rolling) return;
  var dc = parseInt(el.dc.value,10);
  if(!isFinite(dc)){ el.err.textContent='先填一个难度（常见 10 / 15 / 20）'; return; }
  var mod = parseInt(el.mod.value,10) || 0;
  var subject = String(el.subject.value||'').trim();

  var a=d(20), b=d(20);
  var nat = adv>0 ? Math.max(a,b) : adv<0 ? Math.min(a,b) : a;
  var total = nat + mod;

  // 跑团惯例：出 20 大成功、出 1 大失败，与加值和难度无关。
  // 这两种单独标出来 —— 它们通常让剧情走向完全不同的分支。
  var v, cls, win;
  if(nat===20){ v='大成功'; cls='crit'; win=true; }
  else if(nat===1){ v='大失败'; cls='fumble'; win=false; }
  else if(total>=dc){ v='成功'; cls='succ'; win=true; }
  else { v='失败'; cls='failv'; win=false; }

  var outcome = String((win?el.onwin:el.onlose).value||'').trim();
  last = { kind:'check', subject:subject, dc:dc, mod:mod, adv:adv,
           rolls: adv?[a,b]:[a], nat:nat, total:total, verdict:v, win:win, outcome:outcome };

  el.err.textContent='';
  el.verdict.textContent=''; el.verdict.className='';
  el.detail.textContent=''; el.outcome.className='';
  el.tip.textContent='投掷中…';

  animate(String(total), function(){
    el.verdict.textContent=v;
    el.verdict.className=cls;
    var det = '['+(adv?[a,b].join(', '):a)+']';
    if(adv) det += adv>0?' 优势取高 '+nat:' 劣势取低 '+nat;
    if(mod) det += (mod>0?' +':' ')+mod;
    det += '   =' + total + '  对抗 DC ' + dc;
    el.detail.textContent = det;
    if(outcome){ el.outcome.textContent = (win?'→ ':'→ ') + outcome; el.outcome.className='on'; }
    el.tip.textContent = subject || '再点一次重投';
    el.send.disabled = !(canSend||canDraft);
  });
}

el.d20.addEventListener('click', doCheck);
[el.subject, el.onwin, el.onlose, el.dc, el.mod].forEach(function(i){
  i.addEventListener('keydown', function(e){ if(e.key==='Enter') doCheck(); });
});

el.reset.addEventListener('click', function(){
  ['subject','onwin','onlose'].forEach(function(k){ el[k].value=''; });
  el.verdict.textContent=''; el.detail.textContent='';
  el.outcome.className=''; el.outcome.textContent='';
  el.dval.textContent='20'; el.tip.textContent='点击骰子开始';
  el.stage.className=''; last=null; el.send.disabled=true; el.err.textContent='';
});

// ── 纯投骰（不做检定时）──
el.freetoggle.addEventListener('click', function(){
  el.freerow.className = el.freerow.className ? '' : 'on';
});

function parse(expr){
  var s=String(expr||'').replace(/\s+/g,'').toLowerCase();
  var m=s.match(/^(\d*)d(\d+)(kh(\d+)|kl(\d+))?([+-]\d+)?$/);
  if(!m) return null;
  var count=m[1]?parseInt(m[1],10):1, sides=parseInt(m[2],10);
  var kh=m[4]?parseInt(m[4],10):0, kl=m[5]?parseInt(m[5],10):0, mod=m[6]?parseInt(m[6],10):0;
  if(count<1||count>100||sides<2||sides>1000) return null;
  if(kh>count||kl>count) return null;
  return {count:count,sides:sides,kh:kh,kl:kl,mod:mod,expr:s};
}

el.rollf.addEventListener('click', function(){
  if(rolling) return;
  var spec=parse(el.formula.value);
  if(!spec){ el.err.textContent='看不懂这个公式。试试 2d6+3 / 4d6kh3'; return; }
  var rolls=[]; for(var i=0;i<spec.count;i++) rolls.push(d(spec.sides));
  var used=rolls.slice();
  if(spec.kh) used=rolls.slice().sort(function(x,y){return y-x;}).slice(0,spec.kh);
  else if(spec.kl) used=rolls.slice().sort(function(x,y){return x-y;}).slice(0,spec.kl);
  var sum=used.reduce(function(x,y){return x+y;},0)+spec.mod;

  last={ kind:'roll', expr:spec.expr, rolls:rolls, used:used, sum:sum };
  el.err.textContent='';
  el.verdict.textContent=''; el.verdict.className='';
  el.outcome.className='';
  animate(String(sum), function(){
    var det='['+rolls.join(', ')+']';
    if(used.length!==rolls.length) det+=' → 取 ['+used.join(', ')+']';
    if(spec.mod) det+=(spec.mod>0?' +':' ')+spec.mod;
    el.detail.textContent=det;
    el.tip.textContent=spec.expr;
    el.send.disabled=!(canSend||canDraft);
  });
});

// ── 发送：连带问题与后果一起 ──
function compose(){
  if(!last) return '';
  if(last.kind==='roll'){
    return '🎲 '+last.expr+' → '+last.sum+'  ['+last.rolls.join(', ')+']';
  }
  var lines=[];
  lines.push('🎲 '+(last.subject||'检定'));
  var d1='d20'+(last.mod?(last.mod>0?'+':'')+last.mod:'');
  lines.push(d1+' = '+last.total+' vs DC '+last.dc
    + (last.adv>0?'（优势）':last.adv<0?'（劣势）':'')
    + ' → '+last.verdict);
  if(last.outcome) lines.push('→ '+last.outcome);
  return lines.join('\n');
}

el.send.addEventListener('click', async function(){
  if(!last) return;
  el.send.disabled=true;
  var text=compose();
  var ok=false;
  // 线上聊天可以直接发；线下（此时此刻）只有填入输入框这条路 ——
  // 那边的送出函数是从 state 读输入内容的，接不了外部参数。
  try{ ok = await nuo.chat.send(text); }catch(e){}
  if(!ok){ try{ ok = await nuo.chat.draft(text); if(ok) el.err.textContent='已填入输入框，确认后送出'; }catch(e){} }
  if(!ok) el.err.textContent='没有可用的聊天（请在聊天或此时此刻里打开）';
  el.send.disabled=!(canSend||canDraft);
});

// ── 启动 ──
// 权限是用户装的时候批的，插件不能假设自己一定有。探测一次，
// 拿不到的能力对应的按钮直接藏掉，比点了才报错好。
async function probe(){
  try{ await nuo.chat.send(''); canSend=true; }
  catch(e){ canSend = (String(e&&e.message)!=='permissionDenied'); }
  canDraft = canSend;   // draft 与 send 同权限
}

async function init(){
  var s=await nuo.storage.getAll();
  if(s&&s.dc) el.dc.value=s.dc;
  await probe();
  el.send.style.display=(canSend||canDraft)?'':'none';
  el.send.disabled=true;
  el.dc.addEventListener('change', function(){ nuo.storage.set('dc', el.dc.value); });
}

init().then(function(){ nuo.ready(); }).catch(function(e){ nuo.log(String(e&&e.message)); nuo.ready(); });
